const crypto = require('crypto');
const API_KEY = process.env.BINANCE_API_KEY;
const API_SECRET = process.env.BINANCE_API_SECRET;
const BASE      = 'https://fapi.binance.com';
const DASHBOARD = 'http://127.0.0.1:3001';

function sign(params) {
  const obj = {...params, timestamp: Date.now(), recvWindow: 60000};
  const qs = Object.entries(obj).map(([k,v]) => `${k}=${encodeURIComponent(String(v))}`).join('&');
  return qs + '&signature=' + crypto.createHmac('sha256', API_SECRET).update(qs).digest('hex');
}
async function bget(path, params = {}) {
  return this.helpers.httpRequest({ method:'GET', url:`${BASE}${path}?${sign(params)}`, headers:{'X-MBX-APIKEY':API_KEY}, json:true });
}

const now      = Date.now();
const dayStart = new Date(); dayStart.setUTCHours(0,0,0,0);
const startTime = dayStart.getTime();

// ── Fetch paralelo: income + balance + posiciones + DB stats ──────────────────
const [income, balances, positions, dbStats] = await Promise.all([
  bget.call(this, '/fapi/v1/income', { startTime, endTime: now, limit: 1000 }),
  bget.call(this, '/fapi/v2/balance'),
  bget.call(this, '/fapi/v2/positionRisk'),
  this.helpers.httpRequest({ method:'GET', url:`${DASHBOARD}/db/stats`, json:true }).catch(()=>null)
]);

const rows = Array.isArray(income) ? income : [];

// ── Calcular PnL del día ──────────────────────────────────────────────────────
let realized = 0, commission = 0, funding = 0, wins = 0, losses = 0;
const perSym = {};
const tradesByHour = {};

for (const r of rows) {
  const v = parseFloat(r.income || 0);
  if (r.incomeType === 'REALIZED_PNL') {
    realized += v;
    if (v > 0) wins++; else if (v < 0) losses++;
    const s = r.symbol || '';
    if (s) perSym[s] = (perSym[s] || 0) + v;
    // por hora
    const h = new Date(r.time).getUTCHours();
    if (!tradesByHour[h]) tradesByHour[h] = { pnl:0, count:0 };
    tradesByHour[h].pnl += v;
    tradesByHour[h].count++;
  }
  if (r.incomeType === 'COMMISSION') commission += v;
  if (r.incomeType === 'FUNDING_FEE') funding += v;
}

const net          = realized + commission + funding;
const totalTrades  = wins + losses;
const winrate      = totalTrades > 0 ? (wins/totalTrades*100).toFixed(1) : '0.0';
const avgTrade     = totalTrades > 0 ? (realized/totalTrades).toFixed(2) : '0.00';
const profitFactor = losses > 0 && wins > 0
  ? (rows.filter(r=>r.incomeType==='REALIZED_PNL'&&+r.income>0).reduce((s,r)=>s+(+r.income),0) /
     Math.abs(rows.filter(r=>r.incomeType==='REALIZED_PNL'&&+r.income<0).reduce((s,r)=>s+(+r.income),0))).toFixed(2)
  : 'N/A';

// ── Balance ───────────────────────────────────────────────────────────────────
const usdt         = (Array.isArray(balances)?balances:[]).find(b=>b.asset==='USDT') || {};
const balance      = parseFloat(usdt.balance || 0);
const available    = parseFloat(usdt.availableBalance || 0);
const unrealized   = parseFloat(usdt.crossUnPnl || 0);
const marginUsed   = balance - available;
const dailyROI     = balance > 0 ? (net/balance*100).toFixed(2) : '0.00';

// ── Posiciones abiertas ───────────────────────────────────────────────────────
const openPos = (Array.isArray(positions)?positions:[])
  .filter(p => Math.abs(parseFloat(p.positionAmt)) > 0)
  .map(p => ({
    symbol:    p.symbol,
    side:      parseFloat(p.positionAmt) > 0 ? 'LONG' : 'SHORT',
    size:      Math.abs(parseFloat(p.positionAmt)),
    entry:     parseFloat(p.entryPrice),
    mark:      parseFloat(p.markPrice),
    pnl:       parseFloat(p.unRealizedProfit),
    roe:       parseFloat(p.percentage || 0),
    leverage:  parseFloat(p.leverage || 1)
  }));

const totalUnrealized = openPos.reduce((s,p) => s + p.pnl, 0);

// ── DB: trades de hoy con R ───────────────────────────────────────────────────
const recent    = (dbStats?.recent || []);
const todayDB   = recent.filter(t => {
  const d = (t.closed_at || t.opened_at || '').toString().slice(0,10);
  return d === new Date().toISOString().slice(0,10);
});
const closedDB  = todayDB.filter(t => t.pnl_usdt != null);
const avgR      = closedDB.length
  ? (closedDB.reduce((s,t)=>s+(+t.r_final||0),0)/closedDB.length).toFixed(2)
  : '—';
const bestTrade = closedDB.reduce((b,t) => (!b||+t.pnl_usdt>+b.pnl_usdt)?t:b, null);
const worstTrade= closedDB.reduce((b,t) => (!b||+t.pnl_usdt<+b.pnl_usdt)?t:b, null);

// ── Mejor hora del día ────────────────────────────────────────────────────────
const bestHour = Object.entries(tradesByHour)
  .sort((a,b) => b[1].pnl - a[1].pnl)[0];

// ── Top symbols ───────────────────────────────────────────────────────────────
const topSyms = Object.entries(perSym)
  .sort((a,b) => b[1] - a[1]);
const topWin  = topSyms.filter(([,v]) => v > 0).slice(0, 3);
const topLoss = topSyms.filter(([,v]) => v < 0).slice(0, 3);

// ── Semaforo de rendimiento ───────────────────────────────────────────────────
const perfEmoji = net > 5 ? '🟢' : net > 0 ? '🟡' : net > -5 ? '🟠' : '🔴';
const wrEmoji   = +winrate >= 70 ? '🔥' : +winrate >= 50 ? '✅' : '⚠️';

// ── Construir mensaje ─────────────────────────────────────────────────────────
const dateStr = new Date().toISOString().slice(0,10);
const ts      = new Date().toISOString().replace('T',' ').slice(0,16) + ' UTC';

function pnlStr(v) { return (v>=0?'+':'') + '$' + Math.abs(v).toFixed(2); }
function bar(pct, max=10) {
  const f = Math.round(Math.min(Math.abs(pct)/10, 1) * max);
  return '█'.repeat(f) + '░'.repeat(max-f);
}

const lines = [
  '━━━━━━━━━━━━━━━━━━━━━━━',
  `${perfEmoji} DAILY PnL REPORT — ${dateStr}`,
  '━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  '💰 RESULTADO DEL DÍA',
  `  Realized PnL:   ${pnlStr(realized)}`,
  `  Comisiones:     ${pnlStr(commission)}`,
  `  Funding:        ${pnlStr(funding)}`,
  `  ─────────────────────`,
  `  NET TOTAL:      ${pnlStr(net)}   (${dailyROI >= 0 ? '+' : ''}${dailyROI}% del balance)`,
  '',
  '📊 ESTADÍSTICAS',
  `  Trades:    ${totalTrades}   ${wrEmoji} WR: ${winrate}%   [${bar(+winrate)}]`,
  `  Wins:      ${wins}   Losses: ${losses}`,
  `  Avg trade: ${pnlStr(+avgTrade)}   Avg R: ${avgR}R`,
  `  Profit F:  ${profitFactor}x`,
  bestTrade  ? `  Mejor:    ${bestTrade.symbol} ${pnlStr(+bestTrade.pnl_usdt)} (+${(+bestTrade.r_final||0).toFixed(2)}R)` : '',
  worstTrade ? `  Peor:     ${worstTrade.symbol} ${pnlStr(+worstTrade.pnl_usdt)} (${(+worstTrade.r_final||0).toFixed(2)}R)` : '',
  '',
  '💼 CUENTA',
  `  Balance:     $${balance.toFixed(2)}`,
  `  Disponible:  $${available.toFixed(2)}`,
  `  En margen:   $${marginUsed.toFixed(2)}`,
  `  Unrealized:  ${pnlStr(totalUnrealized)}`,
  '',
];

// Top wins
if (topWin.length > 0) {
  lines.push('🏆 MEJORES PARES');
  topWin.forEach(([s,v]) => lines.push(`  ${s.replace('USDT','')}:  ${pnlStr(v)}`));
  lines.push('');
}

// Top losses
if (topLoss.length > 0) {
  lines.push('💀 PEORES PARES');
  topLoss.forEach(([s,v]) => lines.push(`  ${s.replace('USDT','')}:  ${pnlStr(v)}`));
  lines.push('');
}

// Mejor hora
if (bestHour) {
  lines.push('🕐 MEJOR HORA DEL DÍA');
  lines.push(`  ${String(bestHour[0]).padStart(2,'0')}:00 UTC — ${pnlStr(bestHour[1].pnl)} (${bestHour[1].count} trades)`);
  lines.push('');
}

// Posiciones abiertas
if (openPos.length > 0) {
  lines.push(`📈 POSICIONES ABIERTAS (${openPos.length})`);
  openPos.forEach(p => {
    const pnlS = pnlStr(p.pnl);
    const roeS = (p.roe>=0?'+':'') + p.roe.toFixed(1) + '%';
    lines.push(`  ${p.side === 'SHORT' ? '🔴' : '🟢'} ${p.symbol.replace('USDT','')} ${p.leverage}x @ $${p.entry} → ${pnlS} (${roeS})`);
  });
  lines.push('');
}

lines.push(`⏰ ${ts}`);
lines.push('━━━━━━━━━━━━━━━━━━━━━━━');

const text = lines.filter(l => l !== null && l !== undefined).join('\n');
return [{ json: { text } }];

const crypto = require('crypto');
const API_KEY = process.env.BINANCE_API_KEY;
const API_SECRET = process.env.BINANCE_API_SECRET;
const BASE = 'https://fapi.binance.com';
const DASHBOARD = process.env.INTERNAL_DASHBOARD_BASE || 'http://127.0.0.1:3001';
const EXECUTION_ENGINE = process.env.EXECUTION_ENGINE_URL || 'http://position_guard:3091/executions';
const PORTFOLIO_CAPACITY_URL = EXECUTION_ENGINE.replace(/\/executions\/?$/, '/portfolio-capacity');
const EXECUTION_TOKEN = process.env.EXECUTION_ENGINE_TOKEN;

function sign(params = {}) {
  const query = Object.entries({ ...params, timestamp: Date.now(), recvWindow: 60000 })
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`).join('&');
  return query + '&signature=' + crypto.createHmac('sha256', API_SECRET).update(query).digest('hex');
}

async function bget(path, params = {}) {
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${BASE}${path}?${sign(params)}`,
    headers: { 'X-MBX-APIKEY': API_KEY },
    json: true
  });
}

const blockers = [];
let cbStatus = { active: false };
try {
  cbStatus = await this.helpers.httpRequest({ method: 'GET', url: `${DASHBOARD}/cb/status`, json: true });
  if (cbStatus.active) blockers.push({
    code: 'CIRCUIT_BREAKER',
    current: cbStatus.consecutiveSL || 0,
    maximum: 2,
    exceeded: Math.max(0, Number(cbStatus.consecutiveSL || 0) - 2),
    direction: cbStatus.direction || null,
    reason: `Circuit breaker activo por ${cbStatus.expiresIn || 0} minutos`
  });
} catch (error) {
  blockers.push({ code: 'RISK_SERVICE_UNAVAILABLE', reason: error.message });
}

let balance = 0;
let availableBalance = 0;
let dailyPnL = 0;
let dailyPnLPct = 0;
let openPositions = [];
try {
  const startOfDay = new Date();
  startOfDay.setUTCHours(0, 0, 0, 0);
  const [balances, positions, income] = await Promise.all([
    bget.call(this, '/fapi/v2/balance'),
    bget.call(this, '/fapi/v2/positionRisk'),
    bget.call(this, '/fapi/v1/income', { startTime: startOfDay.getTime(), endTime: Date.now(), limit: 1000 })
  ]);
  const usdt = balances.find(row => row.asset === 'USDT') || {};
  balance = Number(usdt.balance || 0);
  availableBalance = Number(usdt.availableBalance || 0);
  openPositions = positions.filter(row => Math.abs(Number(row.positionAmt || 0)) > 0).map(row => ({
    symbol: row.symbol,
    direction: Number(row.positionAmt) > 0 ? 'LONG' : 'SHORT',
    quantity: Math.abs(Number(row.positionAmt)),
    entryPrice: Number(row.entryPrice || 0),
    unrealizedPnl: Number(row.unRealizedProfit || 0)
  }));
  dailyPnL = income.filter(row => row.incomeType === 'REALIZED_PNL')
    .reduce((sum, row) => sum + Number(row.income || 0), 0);
  dailyPnLPct = balance > 0 ? dailyPnL / balance * 100 : 0;
} catch (error) {
  blockers.push({ code: 'EXCHANGE_UNAVAILABLE', reason: error.message });
}

let portfolioCapacity = null;
if (!blockers.some(blocker => blocker.code === 'EXCHANGE_UNAVAILABLE')) {
  try {
    if (!EXECUTION_TOKEN) throw new Error('EXECUTION_ENGINE_TOKEN is not configured');
    portfolioCapacity = await this.helpers.httpRequest({ method: 'GET', url: PORTFOLIO_CAPACITY_URL,
      headers: { Authorization: `Bearer ${EXECUTION_TOKEN}` }, json: true, timeout: 30000 });
    if (!portfolioCapacity.allowed) blockers.push({
      code: 'PORTFOLIO_CAPACITY_FULL',
      reason: portfolioCapacity.primaryReason?.code || 'No capital/risk capacity remains',
      current: { riskPct: portfolioCapacity.risk?.openRiskPct,
        marginUsagePct: portfolioCapacity.account?.marginUsagePct,
        exposurePct: portfolioCapacity.exposure?.totalPct },
      maximum: { riskPct: portfolioCapacity.risk?.maximumRiskPct,
        marginUsagePct: portfolioCapacity.limits?.maxMarginUsagePct,
        exposurePct: portfolioCapacity.limits?.maxExposurePct }
    });
  } catch (error) {
    blockers.push({ code: 'PORTFOLIO_CAPACITY_UNAVAILABLE', reason: error.message });
  }
}

let capitalStatus = { halted: false, reasons: [] };
if (!blockers.some(blocker => blocker.code === 'EXCHANGE_UNAVAILABLE')) {
  try {
    capitalStatus = await this.helpers.httpRequest({
      method: 'GET',
      url: `${DASHBOARD}/api/learning/capital-status?balance=${encodeURIComponent(balance)}`,
      json: true
    });
    if (capitalStatus.halted) blockers.push({
      code: 'CAPITAL_PROTECTION',
      reason: (capitalStatus.reasons || []).join('; '),
      current: { dailyPct: capitalStatus.dailyPct, weeklyPct: capitalStatus.weeklyPct, drawdownPct: capitalStatus.drawdownPct },
      maximum: { dailyPct: 15, weeklyPct: 20, drawdownPct: 25 }
    });
  } catch (error) {
    blockers.push({ code: 'CAPITAL_GUARD_UNAVAILABLE', reason: error.message });
  }
}

const primary = blockers[0] || null;
const passRisk = blockers.length === 0;
console.log(`[RiskV2] pass=${passRisk} balance=${balance.toFixed(2)} positions=${openPositions.length} risk=${portfolioCapacity?.risk?.openRiskPct ?? 'N/A'}% remaining=${portfolioCapacity?.risk?.remainingRiskPct ?? 'N/A'}% slots=${portfolioCapacity?.capacity?.dynamicAdditionalPositions ?? 0} primary=${primary?.code || 'NONE'}`);

return [{ json: {
  passRisk,
  balance: +balance.toFixed(2),
  availableBalance: +availableBalance.toFixed(2),
  dailyPnL: +dailyPnL.toFixed(2),
  dailyPnLPct: +dailyPnLPct.toFixed(2),
  openCount: openPositions.length,
  openSymbols: openPositions.map(position => position.symbol),
  openPositions,
  portfolioCapacity,
  haltReason: primary ? `${primary.code}: ${primary.reason || JSON.stringify(primary.current)}` : null,
  riskDecision: {
    allowed: passRisk,
    primaryReason: primary,
    secondaryReasons: blockers.slice(1),
    controlsEvaluated: ['exchange', 'circuit_breaker', 'capital_guard', 'portfolio_risk',
      'margin_capacity', 'portfolio_exposure', 'symbol_exposure', 'direction_exposure']
  },
  learningCapital: capitalStatus,
  cbActive: !!cbStatus.active
} }];

const d = $input.first().json;
const DASHBOARD = process.env.INTERNAL_DASHBOARD_BASE || 'http://127.0.0.1:3001';

let result;
try {
  result = await this.helpers.httpRequest({
    method: 'POST',
    url: `${DASHBOARD}/api/opportunities/scan`,
    json: true,
    body: {
      openCount: Number(d.openCount || 0),
      openSymbols: d.openSymbols || [],
      openPositions: d.openPositions || [],
      balance: Number(d.balance || 0),
      portfolioCapacity: d.portfolioCapacity || null,
      marketContext: d.marketContext || {}
    },
    timeout: 120000
  });
} catch (error) {
  return [{ json: {
    ...d,
    noSetup: true,
    reason: `OPPORTUNITY_SCAN_FAILED: ${error.message}`,
    opportunityDecision: { primaryReason: { code: 'MARKET_DISCOVERY_UNAVAILABLE', reason: error.message } }
  } }];
}

if (!result.selected) {
  const best = result.ranking?.[0];
  return [{ json: {
    ...d,
    noSetup: true,
    reason: best
      ? `Sin oportunidad elegible: ${best.symbol} score=${best.finalScore}/${best.threshold} motivo=${best.primaryReason}`
      : `Sin candidatos profundos en ciclo ${result.cycleId}`,
    opportunityCycle: result,
    opportunityDecision: best || null
  } }];
}

const selected = result.selected;
console.log(`[OpportunityV2] cycle=${result.cycleId} selected=${selected.symbol} rank=${selected.rank} score=${selected.finalScore}/${selected.threshold}`);
return [{ json: {
  ...d,
  ...selected,
  score: selected.technicalScore,
  finalScore: selected.finalScore,
  direction: selected.direction,
  noSetup: false,
  dynamicThreshold: selected.threshold,
  setupLabel: selected.setupLabel,
  aiResult: {
    regime: selected.regime,
    direction_bias: selected.direction,
    recommended_leverage: 5,
    confidence_adjustment: 0,
    key_risk: selected.hardBlockers?.[0]?.code || 'none',
    reasoning: 'Selección determinista por ranking de portfolio'
  },
  slMultiplier: 1.5,
  tpMultiplier: 2,
  riskReduction: 0,
  leverageOverride: null,
  opportunityCycleId: result.cycleId,
  opportunityUniverse: result.universe,
  opportunityRanking: result.ranking,
  opportunityDecision: selected,
  contributionTable: selected.contributionTable
} }];

const d = $input.first().json;
const { symbol, direction, finalScore, indicators, aiResult, balance, availableBalance, openCount, openSymbols, candles, intelAdjFinal, portfolioCapacity } = d;

const currentPrice = indicators.currentPrice;
const atrVal       = indicators.atr;

// ── Parámetros base ───────────────────────────────────────────────────────────
const BASE_RISK_PCT  = 0.02;
const MAX_MARGIN_PCT = 0.30;
const MIN_RISK_PCT   = 0.005;

// ── Score multiplier ──────────────────────────────────────────────────────────
let scoreMultiplier = 1.0;
if      (finalScore >= 80) scoreMultiplier = 1.5;
else if (finalScore >= 70) scoreMultiplier = 1.25;
else if (finalScore >= 60) scoreMultiplier = 1.0;
else if (finalScore >= 55) scoreMultiplier = 0.7;
else                       scoreMultiplier = 0.5;

// ── Vision multiplier ─────────────────────────────────────────────────────────
const marketState = d.aiVision?.market_state || 'UNKNOWN';
let visionMultiplier = 1.0;
if      (marketState === 'EARLY_TREND') visionMultiplier = 1.3;
else if (marketState === 'MID_TREND')   visionMultiplier = 1.1;
else if (marketState === 'LATE_TREND')  visionMultiplier = 0.6;
else if (marketState === 'PARABOLIC')   visionMultiplier = 0.3;

// ── Régimen multiplier ────────────────────────────────────────────────────────
const regime = aiResult?.regime || 'TRENDING';
let regimeMultiplier = 1.0;
if      (regime === 'TRENDING')        regimeMultiplier = 1.1;
else if (regime === 'RANGING')         regimeMultiplier = 0.8;
else if (regime === 'HIGH_VOLATILITY') regimeMultiplier = 0.7;

// ── 4h multiplier ─────────────────────────────────────────────────────────────
const tf4h = d.tf4h || {};
let tf4hMultiplier = 1.0;
if      (tf4h.status === 'CONFIRMS')    tf4hMultiplier = 1.1;
else if (tf4h.status === 'NEUTRAL')     tf4hMultiplier = 0.95;
else if (tf4h.status === 'CONTRADICTS') tf4hMultiplier = 0.6;

// ── Macro multiplier ──────────────────────────────────────────────────────────
const macroSizeMultiplier = d.marketContext?.size_multiplier || 1.0;

// Portfolio concentration is enforced by capital/risk budgets, not trade count.
// ── Risk reduction desde AI ───────────────────────────────────────────────────
const aiRiskReduction = d.riskReduction || 0;

// ── Riesgo efectivo ───────────────────────────────────────────────────────────
const rawRisk = BASE_RISK_PCT
  * scoreMultiplier
  * visionMultiplier
  * regimeMultiplier
  * tf4hMultiplier
  * macroSizeMultiplier
  * (1 - aiRiskReduction);

const effectiveRisk = Math.min(0.05, Math.max(MIN_RISK_PCT, rawRisk));

// ── Leverage ──────────────────────────────────────────────────────────────────
const maxLeverage = tf4h.status === 'CONTRADICTS' ? 4 : 15;
const leverage = Math.min(Math.max(d.leverageOverride || aiResult?.recommended_leverage || 5, 2), maxLeverage);

// ── SL y TP ───────────────────────────────────────────────────────────────────
const slMultiplier = d.slMultiplier || 1.5;
const tpMultiplier = d.tpMultiplier || 2.0;

// ── Qty ───────────────────────────────────────────────────────────────────────
const slDistance = atrVal * slMultiplier;
const riskAmount = balance * effectiveRisk;
let   qty        = riskAmount / slDistance;

const margin = (qty * currentPrice) / leverage;
if(margin > balance * MAX_MARGIN_PCT){
  qty = (balance * MAX_MARGIN_PCT * leverage) / currentPrice;
}

// ── Capital-aware portfolio caps ──────────────────────────────────────────────
const allocation = portfolioCapacity || {};
const equity = Number(allocation.account?.equity || balance || 0);
const remainingRiskAmount = Number(allocation.risk?.remainingRiskAmount);
const remainingMargin = Number(allocation.capacity?.remainingMargin);
const remainingExposure = Number(allocation.exposure?.remaining);
const maxSymbolExposure = equity * Number(allocation.limits?.maxSymbolExposurePct || 0) / 100;
const maxDirectionExposure = equity * Number(allocation.limits?.maxDirectionExposurePct || 0) / 100;
const currentSymbolExposure = Number(allocation.exposure?.bySymbol?.[symbol] || 0);
const currentDirectionExposure = Number(allocation.exposure?.direction?.[direction] || 0);
const qtyCaps = [qty];
if(Number.isFinite(remainingRiskAmount) && remainingRiskAmount >= 0) qtyCaps.push(remainingRiskAmount / slDistance);
if(Number.isFinite(remainingMargin) && remainingMargin >= 0) qtyCaps.push(remainingMargin * leverage / currentPrice);
if(Number.isFinite(remainingExposure) && remainingExposure >= 0) qtyCaps.push(remainingExposure / currentPrice);
if(maxSymbolExposure > 0) qtyCaps.push(Math.max(0, maxSymbolExposure - currentSymbolExposure) / currentPrice);
if(maxDirectionExposure > 0) qtyCaps.push(Math.max(0, maxDirectionExposure - currentDirectionExposure) / currentPrice);
qty = Math.max(0, Math.min(...qtyCaps));

const pricePrecision = currentPrice >= 1000 ? 1 : currentPrice >= 10 ? 2 : currentPrice >= 1 ? 3 : 4;
const qtyPrecision   = currentPrice >= 1000 ? 3 : currentPrice >= 10 ? 2 : 1;
qty = Math.floor(qty * Math.pow(10, qtyPrecision)) / Math.pow(10, qtyPrecision);

let sl, tp, side;
if(direction === 'LONG'){
  side = 'BUY';
  sl   = +(currentPrice - slDistance).toFixed(pricePrecision);
  tp   = +(currentPrice + slDistance * tpMultiplier).toFixed(pricePrecision);
} else {
  side = 'SELL';
  sl   = +(currentPrice + slDistance).toFixed(pricePrecision);
  tp   = +(currentPrice - slDistance * tpMultiplier).toFixed(pricePrecision);
}

// ── P&L real basado en qty final ─────────────────────────────────────────────
const maxLoss        = +(Math.abs(currentPrice - sl) * qty).toFixed(2);
const maxGain        = +(maxLoss * tpMultiplier).toFixed(2);
const marginRequired = +((qty * currentPrice) / leverage).toFixed(2);

// riskAmount y riskPct consistentes con qty final (no con la estimación previa al truncado)
const actualRiskAmount = maxLoss;
const actualRiskPct    = +(actualRiskAmount / balance * 100).toFixed(2);
const allocationAllowed = allocation.allowed !== false && qty > 0
  && (!Number.isFinite(remainingRiskAmount) || actualRiskAmount <= remainingRiskAmount + 1e-8)
