      console.log(`SL Monitor activado: ${d.symbol} sl=${d.slPrice} entry=${d.entryPrice}`);
      break;
    }catch(e){
      console.log(`SL Monitor intento ${i+1}/3 falló: ${e.message}`);
      if(i < 2) await new Promise(r => setTimeout(r, 1000)); // 1s entre intentos
    }
  }

  if(!slMonitorOk){
    return [{json:{...d,success:false,finalStatus:'LOCAL_STATE_FAILED',failureNotificationSent:false,
      error:`Binance verified the entry but SL Monitor local state failed for ${d.symbol}`}}];
  }

  let slStateConfirmed=false;

