  if(slMonitorOk){
    try{
      await new Promise(r => setTimeout(r, 500)); // reducido de 1000ms a 500ms
      const state = await this.helpers.httpRequest({
        method:  'GET',
        url:     WEBHOOK_GET,
        json:    true,
        timeout: 3000
      });
      const positions = state.positions || {};

      if(!positions[d.symbol]){
        console.log(`⚠️ Health check: ${d.symbol} no aparece — reintentando...`);
        try{
          const retried=await this.helpers.httpRequest({
            method:  'POST',
            url:     WEBHOOK_URL,
            json:    true,
            body:    newPosition,
            timeout: 5000
          });
          slStateConfirmed=Boolean(retried?.positions?.[d.symbol]);
          console.log(`Health check retry ${slStateConfirmed?'confirmed':'unconfirmed'}: ${d.symbol}`);
        }catch(e){
          console.log(`❌ Health check reintento falló: ${e.message}`);
        }
