      for(const sym of Object.keys(positions)){
        const pos = positions[sym];
        if(!pos.qty || pos.qty === 0 || pos.slPrice === 9999){
          console.log(`[HealthCheck] Fantasma detectada: ${sym} qty=${pos.qty} sl=${pos.slPrice}`);
        }
      }
    }catch(e){
      console.log(`Health check error: ${e.message}`);
    }
  }

  if(!slStateConfirmed){
    return [{json:{...d,success:false,finalStatus:'LOCAL_STATE_FAILED',failureNotificationSent:false,
      error:`Binance verified the entry but SL Monitor read-back failed for ${d.symbol}`}}];
  }

  // ── 3. Dashboard (/trade) ─────────────────────────────────────────────────
  try{
    await this.helpers.httpRequest({
      method: 'POST',
      url:    `${DASHBOARD}/trade`,
      json:   true,
      timeout: 5000,
      body: {
        symbol:     d.symbol,
