async function get(path, fallback) {
  try { return await this.helpers.httpRequest({ method:'GET', url:`${DASHBOARD}${path}`, json:true }); }
  catch(e) { console.log(`[WeeklyResearch] GET ${path} error: ${e.message}`); return fallback; }
}
async function post(path, body) {
  try { return await this.helpers.httpRequest({ method:'POST', url:`${DASHBOARD}${path}`, json:true, body }); }
  catch(e) { console.log(`[WeeklyResearch] POST ${path} error: ${e.message}`); return null; }
}
function money(v) { v=Number(v||0); return (v>=0?'+':'-')+'$'+Math.abs(v).toFixed(2); }
function pct(v) { return Number(v||0).toFixed(1)+'%'; }
function list(rows, fn, limit=8) { return (rows||[]).slice(0,limit).map(fn).join('\n') || 'Sin datos reales'; }
function sectionLines(text, patterns) { return String(text||'').split(/\r?\n/).map(l=>l.trim()).filter(Boolean).filter(l=>patterns.some(p=>p.test(l))).slice(0,12); }

